persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers an updated webmail service, which can be seen as a form of reciprocity, as users receive a benefit in exchange for their action (updating their account)."},
    "Scarcity": {"Explanation": "The email creates urgency by stating that failure to act within 24 hours will result in the deactivation of the account, creating a sense of scarcity and prompting immediate action."},
    "Authority": {"Explanation": "The email uses the IT Service Desk Support as an authority figure, implying that they have the right to deactivate accounts and that their request should be followed."},
    "Commitment/Consistency": {"Explanation": "The email does not explicitly reference prior behavior or choices to push further action, so this principle is not present."},
    "Liking": {"Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport, so this principle is not present."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsement, so this principle is not present."}
}

raw_phishing:
{
    "Phishing Characteristics": {"Assessment": "Phishing Email", "Justification": "The email uses a generic greeting and asks the recipient to click a link without providing any context or explanation. It also demands immediate action and threatens account deactivation, which are common phishing tactics."},
    "Phishing Persuasion": {"Assessment": "Phishing Email", "Justification": "The identified persuasion principles (Reciprocity, Scarcity, and Authority) are used inappropriately to manipulate the recipient into taking an action against their best interest. Reciprocity is misused by offering an 'updated webmail' as a reason to update the account, Scarcity is used to create urgency, and Authority is falsely claimed by using the IT Service Desk Support name. These principles are inconsistent with a legitimate email and appear manipulative."}
}

