persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers a discount ($75 off) as a benefit to entice the reader to make a purchase, creating a sense of reciprocity where the reader feels they are getting something in return for their action."},
    "Scarcity": {"Explanation": "The email creates a sense of scarcity by limiting the offer to a specific period (February 15th to 18th), which can create a feeling of urgency to act quickly."},
    "Authority": {"Explanation": "Not present. There is no mention of any authority figure or credible institution that lends authority to the email."},
    "Commitment/Consistency": {"Explanation": "Not present. There is no reference to prior behavior or choices that would prompt further action based on consistency."},
    "Liking": {"Explanation": "Not present. The email does not use familiarity, flattery, or personalization to build trust or rapport with the recipient."},
    "Social proof": {"Explanation": "Not present. There is no reference to other people's participation or endorsement to influence the reader's decision-making process."}
}

