    "Authority": {"Explanation": "The email is from 'American Express,' a well-known and respected financial institution, which lends authority to the message."},
    "Commitment/Consistency": {"Explanation": "The email does not explicitly reference prior behavior or choices to push for further action, so this principle is not present."},
    "Liking": {"Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport, so this principle is not present."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsement, so this principle is not present."}
}

